#include <stdio.h>
int isperfect(int n)
{
  int i, s = 0;
  for (i = 1; i < n; i++)
    if (n % i == 0)
      s += i;
  return s == n;
}
int main(void)
{
  int m, n, found = 0;
  scanf("%d", &m);
  for (n = 1; n <= m; n++)
    if (isperfect(n)) {
      if (found) printf(" ");
      printf("%d", n);
      found = 1;
    }
  if (!found) printf("none");
  printf("\n");
  return 0;
}

